#include <iostream>
#include <cstdio>
using namespace::std;
const int N = 1e6 + 10;
int u[N], v[N];
int c, t;
int n, k;
int main() {
	freopen("hub.in", "r", stdin);
	freopen("hub.out", "w", stdout);
	scanf("%d", &c);
	if(c == 0) {
		printf("1\n2");
		return 0;
	}
	scanf("%d", &t);
	while(t--) {
		scanf("%d%d", &n, &k);
		for(int i = 1; i <= n; i++) {
			scanf("%d%d", &u[i], &v[i]);
		}
		printf("%d\n", n / 5);
	}
	fclose(stdin);
	fclose(stdout);
	return 0;
}

